import axios from 'axios';
import {useEffect, useState } from "react";
function Employee() {
  const [id, setId] = useState('');
  const [name, setName] = useState('');
  const [address, setAddress] = useState('');
  const [fee, setFee] = useState('');
  const [students, setUsers] = useState([]);
  useEffect(() =>{
    (async()=>await Load())();
  }, []);

  async function Load(){
    const result = await axios.get(
      "http://127.0.0.1:8000/student/");
      setUsers(result.data);
      console.log(result.data);
  }

  async function save(event){
    event.preventDefault();
    try{
      await axios.post("http://127.0.0.1:8000/student/",{
        name: name, 
        address: address,
        fee: fee
      });
      alert("Employee Registration Successful");
      setId("");
      setName("");
      setAddress("");
      setFee("");
      Load();
    }
    catch(err){
      alert("User Registration Failed");
    }
  }

  async function editEmployee(employees){
    setName(employees.name);
    setAddress(employees.address);
    setFee(employees.fee);
    setId(employees.id);
  }

  async function DeleteEmployee(id){
    await axios.delete("http://127.0.0.1:8000/student/"+id);
    alert("Employee Deleted Successfully");
    console.log("Data Deleted Failed");
    Load();
  }


  // async function DeleteEmployee(id) {
  //   const url = "http://localhost:8000/api/delete + id";
    
  //   try {
  //     const response = await axios.delete(url);
  //     console.log('Record deleted successfully:', response.data);
  //   } catch (error) {
  //     console.error('There was an error deleting the record:', error.response ? error.response.data : error.message);
  //   }
  // }

  async function update(event){
    event.preventDefault();
    try{
      await axios.put("http://127.0.0.1:8000/student/" + students.find(u => u.id === id).id || id,{
        id: id,
        name: name,
        address: address,
        fee: fee
      });
      alert("Record Updated Successfully");
      setId("");
      setName("");
      setAddress("");
      setFee("");
      Load();
    }
    catch(err){
      alert("User Registration Failed");
    }
  }

  if(employees.length <= 0) return null;

    return (
      <div className="App">
        <div className="container">
          <form >
        <div className="form-group">
            <label className="form-label"><h1>Employee Management System</h1></label>
            <input type="Text" className="form-control" id="employee_id" hidden
            value={id}
            onChange={(event)=>{
              setId(event.target.value);
            }}/>           
           
          </div>

          <div className="mb-3">
            <label className="form-label">Employee Name</label>
            <input type="Text" className="form-control" id="employeeName" placeholder = "Enter Employee Name"
            value={name}
            onChange={(event)=>{
              setName(event.target.value);
            }}/>           
           
          </div>

          <div className="mb-3">
            <label className="form-label">Employee Address</label>
            <input type="Text" className="form-control" id="employeeAddress" placeholder = "Enter Employee Address"
            value={address}
            onChange={(event)=>{
              setAddress(event.target.value);
            }}/>           
           
          </div> 

          <div className="mb-3">
            <label className="form-label">Employee fee</label>
            <input type="Text" className="form-control" id="employeeFee" placeholder = "Enter Employee Phone"
            value={fee}
            onChange={(event)=>{
              setFee(event.target.value);
            }}/>           
           
          </div>
          <button className="btn btn-primary" onClick={save}>Register</button>
          <button className="btn btn-warning" onClick={update}>Update</button>
        </form>

        {/* <table className="table table-dark" align="center">
        <thead>
          <tr>
            <th scope='col'>Employee ID</th>
            <th scope='col'>Employee Name</th>
            <th scope='col'>Employee Address</th>
            <th scope='col'>Employee Mobile</th>

            <th scope='col'> Action</th>
          </tr>
        </thead>
        {employees.map(function fj(employee){
          return(
            <tbody>
              <tr>
                <th scope="row">{employee.id}</th>
                <td>{employee.name}</td>
                <td>{employee.address}</td>
                <td>{employee.mobile}</td>
                <td>
                  <button type="button" className="btn btn-warning" onClick={() => editEmployee(employee)} > Edit </button>
                  <button type="button" className="btn btn-danger" onClick={() => DeleteEmployee(employee.id)} > Delete </button>
                </td>
              </tr>
            </tbody>
          );
        })}
      </table> */
      <table className="table table-dark" align="center">
  <thead>
    <tr>
      <th scope="col">Employee ID</th>
      <th scope="col">Employee Name</th>
      <th scope="col">Employee Address</th>
      <th scope="col">Employee Fee</th>
      <th scope="col">Action</th>
    </tr>
  </thead>
  <tbody>
    {employees.map((employee) => (
      <tr key={employee.id}>
        <th scope="row">{employee.id}</th>
        <td>{employee.name}</td>
        <td>{employee.address}</td>
        <td>{employee.fee}</td>
        <td>
          <button
            type="button"
            className="btn btn-warning"
            onClick={() => editEmployee(employee)}
          >
            Edit
          </button>
          <button
            type="button"
            className="btn btn-danger"
            onClick={() => DeleteEmployee(employee.id)}
          >
            Delete
          </button>
        </td>
      </tr>
    ))}
  </tbody>
</table>

      }
        </div>
      </div>

      
    );
  }
  
  export default Employee;
